// The prompt each kind of agent runs under is the user's, held as a file in
// their workspace (prompts/<role>.md) and read by `Prompts` below. The text
// itself lives in Rust (src/prompts.rs) so there is one definition of what a
// model is really sent -- a copy here would drift from it -- and so the rules
// a user's edit cannot remove travel with every composition.
//
// SYSTEM_PROMPT is what a chat is told, composed from that file plus those
// rules. It is a function, not a constant, because the file can change under
// a running app.
// TAKES THE MODEL, because two of the notes are composed on it. `VERIFY_NOTE` and
// `QUIET_NOTE` were each measured worth their tokens on some models and not on others
// (dev/PROMPT_NOTES.md), and `prompts::measured_spare` drops one only where a measurement
// says so by name. A caller with no model in hand passes nothing and gets every note,
// which is the safe answer: an absent note costs a turn, a needless one costs about a
// hundred tokens.
// `steer` is the steering notes to tell it, one per line, where a chat is built with any (`ensureApp`).
export function SYSTEM_PROMPT(model, steer) { return Prompts.role('chat', model, steer); }

// ── The credential a push travels with ─────────────────────
//
// The engine holds it in ONE `thread_local` belonging to the wasm instance, and
// a reload builds a fresh instance -- so the engine's copy is gone on every
// load, and every account boundary (switch, add, erase, restore, take an
// update) IS a reload. The page is therefore the only thing that can bring it
// back, and it has to do so on every path that ends in a usable app: a push
// that worked yesterday and silently refuses today is the failure this exists
// to prevent.
//
// There is exactly one such path, and it is established from the code rather
// than assumed. A reload always locks -- `identity.js` holds the wrapping key
// in memory alone, so `isUnlocked()` is false at boot however the tab got there
// -- and every way past the gate ends in `completeUnlock`: a typed passphrase
// and a freshly created account both through `idPrimary`, a passkey and a
// passkey adoption both through `passkeyUnlock`. `completeUnlock` awaits
// `afterUnlock`, which is where the replay goes. The one boot that does NOT
// reach it is the browser-only path with no identity at all -- and that path
// has nothing stored to replay, because storing it needs an identity to wrap
// it under.
//
// So: `afterUnlock` replays, `lockApp` clears, `doChangePassphrase` re-seals,
// and nothing else touches it.

/// Hand the held credential to the engine, or clear it there.
///
/// The engine holds one credential for the whole wasm instance rather than one
/// per agent, so any built app will do; `tools()` is simply the one that always
/// exists. An empty token CLEARS it, which is what makes this the same call for
/// setting and for forgetting.
///
/// # Returns
/// Whether a credential is held afterwards.
export function applyPushCred() {
	try {
		return !!tools().set_push_cred(
			pg.cfg.pushHost || '', pg.cfg.pushUser || '', pg.cfg.pushToken || '');
	} catch (e) {
		// A host the engine will not have, or a token carrying something that
		// cannot travel in a header. This is the SILENT path -- the replay, and the
		// clear -- so there is nobody to tell; the panel reports its own failures
		// where the user is standing in front of it. A credential the engine
		// refuses is a credential that is not held, which is the safe reading.
		return false;
	}
}

/// The host the ENGINE says a push would reach, or empty.
///
/// Asked of the engine and never of storage. Those two differ in exactly the
/// case that matters: a reload empties the engine's copy, and a panel drawn
/// from `localStorage` would report a push configured while every push was
/// being refused.
export function pushHostHeld() {
	try { return tools().push_host() || ''; } catch (e) { return ''; }
}

/// The user name a token travels as at `host`.
///
/// Inferred rather than asked for, and that is the whole reason there are two
/// boxes and not three. It is a per-forge constant and not a choice: GitHub
/// wants `x-access-token`, which the engine supplies for an empty value, and
/// GitLab wants `oauth2`. A box labelled "user name" is a box a person fills in
/// with their own login, which authenticates nowhere and fails with a message
/// that names neither the box nor the reason.
///
/// # Arguments
/// * `host` - The bare host, as typed.
function pushUserFor(host) {
	return /gitlab/i.test(String(host || '')) ? 'oauth2' : '';
}

/// Draw the push panel: the host that is set, and an empty token box.
///
/// The token box starts empty every time and is emptied again after a save. The
/// token is write-only from here on -- there is no accessor for it in the
/// engine and no reason for it to be back on screen, and a field redrawn with a
/// secret in it is a secret in the DOM for anything that can read the DOM.
export function fillPushSettings() {
	var h = document.getElementById('cfg-push-host');
	if (h) h.value = pg.cfg.pushHost || '';
	setSecret(document.getElementById('cfg-push-token'), '');
	var n = document.getElementById('push-note');
	if (n) n.textContent = '';
	renderPushState();
}

/// The one line that says what a push would do right now.
export function renderPushState() {
	var el = document.getElementById('push-state');
	if (!el) return;
	var held = pushHostHeld();
	el.textContent = held ? t('push.set', { host: held }) : t('push.none');
}

/// Take what is in the two boxes and make it the credential, or remove the one
/// held.
///
/// The engine is asked BEFORE anything is stored, because the engine is the one
/// place that decides what a host and a token may be -- so a refusal leaves
/// nothing behind in storage to be replayed on the next load.
export async function savePushCred() {
	var note = document.getElementById('push-note');
	var hostEl = document.getElementById('cfg-push-host');
	var tokEl  = document.getElementById('cfg-push-token');
	if (!note || !hostEl || !tokEl) return;
	var host  = (hostEl.value || '').trim();
	hideSecret(tokEl);
	var token = getSecret(tokEl).trim();
	note.textContent = '';
	// An empty token REMOVES the credential rather than storing an empty one, so
	// it is not an error and it needs no host. Same call, and the engine's own
	// rule: "there is no credential" is a sentence a model can act on where
	// "authentication failed" is not.
	if (!token) {
		pg.cfg.pushHost = ''; pg.cfg.pushUser = ''; pg.cfg.pushToken = ''; pg.cfg.pushTokenEnc = '';
		saveCfg(pg.cfg);
		applyPushCred();
		hostEl.value = '';
		setSecret(tokEl, '');
		renderPushState();
		mark(note, '', t('push.cleared'));
		return;
	}
	if (!host) { mark(note, '', t('push.err_host')); hostEl.focus(); return; }
	var user = pushUserFor(host);
	var held;
	try { held = tools().set_push_cred(host, user, token); }
	catch (e) { note.textContent = friendlyError(e); hostEl.focus(); return; }
	if (!held) { mark(note, '', t('push.err_not_held')); return; }
	// The engine folds the host -- 'GitHub.com/' becomes 'github.com' -- so what
	// is stored is what a push will actually reach, and the box agrees with it.
	pg.cfg.pushHost  = pushHostHeld() || host;
	pg.cfg.pushUser  = user;
	pg.cfg.pushToken = token;
	// Wrapped, or not stored at all. There is no plaintext fallback here: see
	// `saveCfg`. The host and the inferred user name are not secrets and are
	// kept either way, so a browser-only user retypes only the token.
	var kept = false;
	pg.cfg.pushTokenEnc = '';
	if (window.DaimondIdentity && DaimondIdentity.isUnlocked()) {
		try { pg.cfg.pushTokenEnc = await DaimondIdentity.wrap(token); kept = true; }
		catch (e) { pg.cfg.pushTokenEnc = ''; }
	}
	saveCfg(pg.cfg);
	hostEl.value = pg.cfg.pushHost;
	setSecret(tokEl, '');
	renderPushState();
	mark(note, '', kept ? t('push.saved') : t('push.session_only'));
}

	// ── The Admin panel ────────────────────────────────────────

/// As `isUnreachable`, for an error object straight out of a `catch`.
///
/// Does the same stripping `friendlyError` does before testing, because a raw error carries
/// the fe2o3 source frames and the JsValue box around the sentence that matters.
export function offline(raw) {
	var s = String(raw == null ? '' : (raw && raw.message ? raw.message : raw));
	return isUnreachable(stripAnsi(s).replace(/src\/[^\s":]+\.rs:\d+:?/g, ' '));
}

/// The host a road failure names (`could not reach <host>`, `TLS handshake with <host>`, the
/// engine's own words in src/llm.rs), without its port, or '' when it names none: "the provider"
/// and the tab's "that endpoint" are not hosts.
function roadHost(s) {
	var m = /(?:could not reach|TLS handshake with)\s+((?:[a-z0-9-]+\.)+[a-z0-9-]+|localhost|\[[0-9a-f:]+\])/i
		.exec(String(s == null ? '' : s));
	return m ? m[1] : '';
}

/// The host a keyed row names (`say.v.host`), when it is one by `roadHost`'s own test, else ''.
/// A runner's words are not trusted to be a host because they sit where one goes.
function keyedHost(h) {
	return typeof h === 'string' && h && roadHost('could not reach ' + h) === h ? h : '';
}

/// A failed turn's error row that broke on ANOTHER device's road, as its seat reason
/// ("argonaut can't reach openrouter.ai", the sentence on hover or tap), or null (RUNNER-ROAD,
/// owner 25 Oct). Where it failed is the row's `ranOn`, stamped by whichever device ran the
/// turn, never read from the words: a road failure here, or a row with no `ranOn`, keeps the
/// tab's own text, which points at this device's Settings and connection. A runner's fault
/// never does.
export function runnerRoad(m) {
	if (!m || m.role !== 'error_log' || !m.ranOn || String(m.ranOn) === String(selfDeviceId())) return null;
	var s = stripAnsi(String(m.content == null ? '' : m.content)).replace(/src\/[^\s":]+\.rs:\d+:?/g, ' ');
	// A native runner's keyed row says it was the road by its key, and names the host in
	// its params (RT-C); the words are read only where the key is absent or names none.
	var keyed = !!(m.say && m.say.k === 'err.unreachable');
	if (!keyed && !isUnreachable(s)) return null;
	var name = deviceLabelFor(m.ranOn) || t('devices.another');	// never "This device": it is not this one
	var host = (keyed && m.say.v && keyedHost(m.say.v.host)) || roadHost(s);
	return seatReason(host ? { k: 'runner_road', vars: { name: name, host: host } }
		: { k: 'runner_road_any', vars: { name: name } });
}

/// The sentence to SHOW for a tool call that did not complete.
///
/// A refusal is already a whole sentence, written by the door that refused and meant
/// for the person reading it; `friendlyError` would collapse its paragraphs and hunt
/// it for status codes, so it is shown as it stands. Anything else is raw error text
/// and wants prettifying. The same rule `renderToolResult` follows, in one place the
/// panels can share -- and it decides on the OUTCOME, never on the words.
export function toolReason(r) {
	var txt = r && typeof r.text === 'string' ? r.text : '';
	return r && r.outcome === 'refused' ? stripAnsi(txt) : friendlyError(txt);
}

export function clearChat() {
	// Emptying the thread from outside a render (the empty state, a daimon view
	// swap) leaves what `renderHistory` last drew no longer on screen, so the next
	// render must not append onto it. See `_renderSynced`.
	if (!pg._renderingHistory) pg._renderSynced = false;
	chatOutput.innerHTML = ''; pg.curAsstDiv = null; pg.curAsstText = '';
	// The card went with the thread. A reference left standing here would have the
	// next conversation's first answer close a question drawn in the last one.
	pg._askCard = null; pg._askJust = false;
	// The live-turn tile state pointed into the thread that has just been emptied.
	pg.liveThink = null; pg.lastToolBlock = null;
	// The turns belonged to the thread that has just been thrown away. Numbering them from
	// scratch is what keeps a turn number meaning "the nth question in THIS chat", which is
	// the assumption the fold relies on when it maps a ticked turn back to a message.
	pg._turn = 0; pg._jumpAt = -1; pg._turnMarks = [];
	pg._handoffTurn = -1;
	setSelectMode(false);
	syncJumps();
}

/// The centre with no chat in it -- which on a fresh account is the first thing the
/// app shows anybody.
///
/// A LONE "+ New chat" USED TO BE THE WHOLE OF IT, on the reasoning that the panel
/// should open straight on the one action there is to take. That was true of the
/// panel and false of the moment: on a first run the status strip said "No model
/// connected" in red, the Admin drawer was over the rail, and nothing on screen said
/// that a model has to be connected before a chat can answer -- so the one action on
/// offer was the one that could not work yet (audit 2026-09-15, GEN-01).
///
/// So it is three steps, and the one the account is actually AT is the live button.
/// The steps are what a person does, in order: connect a model, say something, keep
/// what worked. Step 3 is never the live one -- there is nothing to keep from an
/// empty centre -- and is drawn so that somebody can see where this is going.
export function renderEmptyState() {
	clearChat();
	chatInputBar.style.display = 'none';       // no input until a chat is started
	var wrap = document.createElement('div');
	wrap.className = 'empty-state start-here';
	var M = window.DaimondModels;
	var connected = !!(M && M.ready());

	var ol = document.createElement('ol');
	ol.className = 'start-steps';
	/// One step. `live` makes it the button; the rest are labels and are not
	/// pressable, because a step you cannot take yet is not an offer.
	var step = function (n, label, live, go) {
		var li = document.createElement('li');
		li.className = 'start-step' + (live ? ' on' : '');
		var num = document.createElement('span');
		num.className = 'start-num';
		num.textContent = String(n);
		li.appendChild(num);
		if (live) {
			var b = document.createElement('button');
			b.className = 'empty-new-session start-go';
			b.textContent = label;
			b.addEventListener('click', go);
			li.appendChild(b);
		} else {
			var sp = document.createElement('span');
			sp.className = 'start-label';
			sp.textContent = label;
			li.appendChild(sp);
		}
		ol.appendChild(li);
	};
	step(1, tOr('start.connect', 'Connect a Model'), !connected,
		function () { openSettings(t('astat.no_model')); });
	step(2, tOr('start.say_hello', 'Say Hello'), connected,
		function () { newChat(); });
	step(3, tOr('start.keep', 'Keep what works as a diamond'), false, null);
	wrap.appendChild(ol);
	chatOutput.appendChild(wrap);
}
